/**
 * Dreams and the Pit
 * ------------------
 * The brothers throw Joseph into an empty pit, then sell him to Ishmaelites for twenty shekels of silver. Stage: a dry pit in the wilderness at dusk, a boy at the bottom looking up, the brothers eating bread at the top; a caravan arriving, the sun going down like a wound.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: bread
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joseph-kit.js.
 */

import { THREE, createScene, tent, firepit, wheat, person } from './joseph-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2880977688, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -22.0, 0, -15.1, 1.35, 0xa8704a, W.r() * 6);
    tent(W, group, 27.2, 0, -17.2, 0.93, 0xd8c8a0, W.r() * 6);
    tent(W, group, 22.8, 0, -5.4, 1.02, 0xc8b088, W.r() * 6);
    tent(W, group, -26.9, 0, -15.0, 0.94, 0xa8704a, W.r() * 6);
    firepit(W, group, -1.0, 0, 2.1, 1.0);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x321d0f, head: 0x382112 });

    /* hero: the bread */
    for (let i = 0; i < 3; i++) {
        W.add(group, W.G('dod', 0.5), W.mat(0xd8b878, { rough: 0.7 }), [0 - 1 + i, 0.35, 0 + (i % 2) * 0.8 - 0.4], { s: [1, 0.5, 0.8] });
    }
    W.disc([0, 3.5, -10], 3, 0x3b2212, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2d1a0e, ry: 0.06, s: 1.17 });

    return W.finish();
}

export default { build };
